        for (let i = 1; i < timeline.length; i++) {
            expect(timeline[i] - timeline[i - 1]).toBe(2_000);
        }
        expect(values.every((v) => v >= 0 && v <= 100)).toBe(true);
        expect(timeline[timeline.length - 1]).toBe(Date.now());
